package ui

import (
	"bytes"
	_ "embed"
	"image"
	"image/png"
	"sync"

	"gioui.org/op/paint"
	"golang.org/x/image/draw"
)

// logoPNG is the app tile without margins (generated by scripts/icongen
// from packaging/logo-source.png).
//
//go:embed assets/logo.png
var logoPNG []byte

var (
	logoMx    sync.Mutex
	logoSrc   image.Image
	logoSizes = map[int]paint.ImageOp{} // by pixel size
)

// logoAt returns the logo pre-scaled to px×px with a high-quality filter:
// the GPU's bilinear sampling can't shrink 256 px to ~24 px without
// aliasing, so the image is drawn 1:1 instead.
func logoAt(px int) paint.ImageOp {
	logoMx.Lock()
	defer logoMx.Unlock()
	if op, ok := logoSizes[px]; ok {
		return op
	}
	if logoSrc == nil {
		img, err := png.Decode(bytes.NewReader(logoPNG))
		if err != nil {
			img = image.NewNRGBA(image.Rect(0, 0, 1, 1))
		}
		logoSrc = img
	}
	dst := image.NewNRGBA(image.Rect(0, 0, px, px))
	draw.CatmullRom.Scale(dst, dst.Rect, logoSrc, logoSrc.Bounds(), draw.Src, nil)
	op := paint.NewImageOp(dst)
	logoSizes[px] = op
	return op
}

// drawLogo draws the app logo in a size×size dp square.
func drawLogo(gtx C, size int) D {
	s := gtx.Dp(unitDp(size))
	if s <= 0 {
		return D{}
	}
	op := logoAt(s)
	op.Add(gtx.Ops)
	paint.PaintOp{}.Add(gtx.Ops)
	return D{Size: image.Pt(s, s)}
}
